// Minimal pseudo-code illustrating CAS-based fault claim
typedef struct { volatile int claimed; int page; int task_id; } FaultReq;
void handle_fault(FaultReq* fr) {
  if (__sync_bool_compare_and_swap(&fr->claimed, 0, 1)) {
    // perform page-in (IO or zero-fill)
    io_submit(fr);
    complete_fault(fr);
  } else {
    enqueue_fault(fr);
  }
}
```

